import {
  DEMO_DATA_NOTICE,
  DEMO_INDEX_CATALOGUE,
  DEMO_RECORDS,
  LOCATION_FACTOR_POLICY,
  calculateHistoricalBasis,
  calculatePrice,
  formatMoney,
  formatNumber,
  makeSnapshot,
  searchRecords,
} from "./src/domain.mjs";
import { importWorkbookFile, MAX_WORKBOOK_BYTES, validateImport } from "./src/importer.mjs";
import { listDatabases, saveDatabase, loadWorkspace, saveWorkspace, storageDescription } from "./src/storage.mjs";

const app = document.querySelector("#app");
const PARSER_VERSION = "SheetJS CE 0.20.3 · vendored";
const state = {
  ready: false, page: "dashboard", mode: "production",
  project: { name: "New Project Estimate", number: "AVA-2026-001", client: "Multiconsult internal workspace", country: "Kenya", targetYear: 2030, currency: "USD" },
  filters: { query: "", equipmentType: "All equipment", voltage: "Any voltage", rating: "Any rating", manufacturer: "Any manufacturer", country: "Any country" },
  records: [], databases: [], items: [], revisions: [],
  indirectCosts: [
    { id: "engineering", name: "Project engineering", enabled: false, type: "percent", applied: 0, basis: "Direct equipment total", rationale: "User-entered only; no automatic percentage." },
    { id: "management", name: "Project management", enabled: false, type: "percent", applied: 0, basis: "Direct equipment total", rationale: "User-entered only; no automatic percentage." },
    { id: "contingency", name: "Contingency", enabled: false, type: "percent", applied: 0, basis: "User/project risk basis required.", rationale: "User-entered only; no automatic percentage." },
    { id: "custom", name: "Other custom cost", enabled: false, type: "absolute", applied: 0, basis: "Absolute project currency", rationale: "User-entered only; no automatic percentage." },
  ],
  builder: null, modal: null, pendingImport: null, importStage: 0, importError: "", lastImport: null, toast: "",
};
const pageMeta = { dashboard: ["Workspace", "Dashboard"], search: ["Estimate workflow", "Equipment search"], builder: ["Estimate workflow", "Price builder"], estimate: ["Estimate workflow", "Project cost estimate"], databases: ["Data management", "Databases"], existing: ["Valuation", "Existing asset valuation"], basis: ["Governance", "Basis & export"], settings: ["Governance", "Settings"] };
const icons = { dashboard: "⌂", search: "⌕", estimate: "▤", databases: "▥", existing: "◈", basis: "↗", settings: "⚙" };

function esc(value) { return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#039;"); }
function dateLabel() { return new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "short", year: "numeric" }).format(new Date()); }
function qualityClass(value) { return String(value || "review").toLowerCase().replaceAll(" ", "-"); }
function typeOptions(values, selected) { return values.map((value) => `<option value="${esc(value)}" ${value === selected ? "selected" : ""}>${esc(value)}</option>`).join(""); }
function currentRecords() { return state.mode === "demo" ? DEMO_RECORDS : state.records; }
function currentResults() { return searchRecords(currentRecords(), state.filters); }
function safeCalculate(record, settings) { try { return calculatePrice(record, settings); } catch (error) { return { error: error.message, historicalBasis: 0, targetUnitCost: 0, total: 0, quantity: Number(settings?.quantity) || 0, escalation: { factor: 1, label: "Blocked", basis: error.message }, locationFactor: Number(settings?.locationFactor) || 0, amounts: [] }; } }
function safeBasis(record) { try { return calculateHistoricalBasis(record).historicalBasis; } catch { return null; } }
function currentItemRows() { return state.items.map((item) => ({ ...item, calc: safeCalculate(item.record, item.settings) })); }
function totals() { const rows = currentItemRows(); const direct = rows.reduce((sum, row) => sum + (row.calc.error ? 0 : row.calc.total), 0); const indirect = state.indirectCosts.filter((item) => item.enabled).reduce((sum, item) => sum + (item.type === "percent" ? direct * (Number(item.applied) || 0) : Number(item.applied) || 0), 0); return { rows, direct, indirect, total: direct + indirect }; }
function refreshRecords() { state.records = state.databases.filter((db) => db.enabled !== false && db.status !== "archived").flatMap((db) => db.records || []); }
function persist() { saveWorkspace({ mode: state.mode, project: state.project, items: state.items, revisions: state.revisions, indirectCosts: state.indirectCosts }).catch(() => {}); }
function showToast(message) { state.toast = message; render(); setTimeout(() => { if (state.toast === message) { state.toast = ""; render(); } }, 3000); }

function navItem(id, label) { return `<button class="nav-item ${state.page === id ? "active" : ""}" data-action="navigate" data-page="${id}"><span class="nav-icon">${icons[id] || "•"}</span><span>${label}</span></button>`; }
function layout(content) { const [group, current] = pageMeta[state.page] || pageMeta.dashboard; const sourceLabel = state.mode === "demo" ? "Training demo" : state.records.length ? `${state.records.length} imported records` : "No source loaded"; return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">AV</div><div class="brand-name">Asset Valuation<span class="brand-sub">Automation</span></div></div><nav aria-label="Primary navigation"><div class="nav-group"><div class="nav-label">Workspace</div>${navItem("dashboard", "Dashboard")}${navItem("search", "Equipment search")}${navItem("estimate", "Project estimate")}</div><div class="nav-group"><div class="nav-label">Data management</div>${navItem("databases", "Databases")}${navItem("existing", "Existing assets")}</div><div class="nav-group"><div class="nav-label">Governance</div>${navItem("basis", "Basis & export")}${navItem("settings", "Settings")}</div></nav><div class="sidebar-foot"><span class="status-dot"></span>${esc(sourceLabel)}<br/><span class="mono">Local · private · v0.2</span></div></aside><main class="main" id="main-content"><header class="topbar"><div class="crumb">${esc(group)} <span>/</span> <strong>${esc(current)}</strong></div><div class="top-actions"><div class="env-pill">${state.mode === "demo" ? "Demo mode" : "Production mode"} · local</div><div class="avatar">MC</div></div></header><div class="content">${content}</div></main>${state.modal ? renderModal() : ""}<div class="toast ${state.toast ? "show" : ""}" role="status">${esc(state.toast)}</div></div>`; }
function pageHead(eyebrow, title, lede, actions = "") { return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p class="lede">${esc(lede)}</p></div><div class="page-actions">${actions}</div></div>`; }
function notice(text, title = "Source data status", cls = "") { return `<div class="notice ${cls}" role="status"><div class="notice-icon">i</div><div><strong>${esc(title)}</strong><span>${esc(text)}</span></div></div>`; }
function sourceNotice() { if (state.mode === "demo") return notice(`${DEMO_DATA_NOTICE} Use production mode after importing an approved workbook.`, "Training demo is active", "warning"); if (!state.records.length) return notice("Production mode is empty. Upload a workbook to analyse, map, validate, preview and commit searchable source rows. Nothing is uploaded to a server.", "No production source database loaded", "warning"); return notice(`${state.records.length} searchable records from ${state.databases.filter((db) => db.enabled !== false).length} local database${state.databases.filter((db) => db.enabled !== false).length === 1 ? "" : "s"}. Source currency and cell-level lineage are retained.`, "Imported source data"); }

function renderDashboard() { const { direct } = totals(); return pageHead("Engineering workspace", "Asset valuation automation", "A traceable workspace for historical cost evidence, transparent escalation and project estimates.", `<button class="btn btn-primary" data-action="navigate" data-page="databases">Import source workbook</button><button class="btn" data-action="navigate" data-page="search">Search evidence</button>`) + sourceNotice() + `<div class="grid grid-4"><div class="card metric"><div class="metric-label">Active project</div><div class="metric-value">${state.items.length ? "1" : "0"}</div><div class="metric-meta">${state.items.length ? "Draft estimate in progress" : "No estimate items yet"}</div></div><div class="card metric"><div class="metric-label">Equipment lines</div><div class="metric-value">${state.items.length}</div><div class="metric-meta">Selected source records</div></div><div class="card metric"><div class="metric-label">Direct cost</div><div class="metric-value">${direct ? formatMoney(direct, 0, state.project.currency) : "—"}</div><div class="metric-meta">Fixed-point calculation engine</div></div><div class="card metric"><div class="metric-label">Source databases</div><div class="metric-value">${state.databases.length}</div><div class="metric-meta">${state.records.length} committed rows · ${state.mode === "demo" ? "demo overlay" : "production"}</div></div></div><div class="section-title"><h2>Estimate workflow</h2><span class="muted tiny">Evidence → calculation → export</span></div><div class="card workflow"><div class="step ${state.records.length || state.mode === "demo" ? "done" : "current"}"><div class="step-dot">1</div><div><div class="step-label">Source data</div><div class="step-state">${state.records.length || state.mode === "demo" ? "Available locally" : "Awaiting workbook"}</div></div></div><div class="step ${state.items.length ? "done" : "current"}"><div class="step-dot">2</div><div><div class="step-label">Find equipment</div><div class="step-state">Technical relevance first</div></div></div><div class="step"><div class="step-dot">3</div><div><div class="step-label">Build price</div><div class="step-state">Components & escalation</div></div></div><div class="step"><div class="step-dot">4</div><div><div class="step-label">Review estimate</div><div class="step-state">Direct & indirect costs</div></div></div><div class="step"><div class="step-dot">5</div><div><div class="step-label">Export</div><div class="step-state">Nine traceability sheets</div></div></div></div><div class="grid grid-2" style="margin-top:16px"><div class="card"><div class="panel-head"><div><h2>Current project</h2><p>${esc(state.project.number)} · ${esc(state.project.client)}</p></div><button class="btn btn-sm" data-action="navigate" data-page="estimate">Open estimate</button></div><div class="panel-body">${state.items.length ? `<div class="mini-list">${currentItemRows().slice(0, 4).map((row) => `<div class="mini-row"><div class="mini-icon">◫</div><div class="mini-copy"><div class="mini-title">${esc(row.record.description)}</div><div class="mini-meta">Qty ${formatNumber(row.calc.quantity, 0)} · ${row.calc.error ? "Blocked" : formatMoney(row.calc.total, 0, row.record.currency)} · ${esc(row.record.reference)}</div></div><span class="quality ${qualityClass(row.record.quality)}">${esc(row.record.quality)}</span></div>`).join("")}</div>` : `<div class="empty-state"><div class="empty-icon">⌁</div><h3>No equipment selected</h3><p class="tiny">Start with an evidence-backed search. Similar records remain separate from selectable source bases.</p><button class="btn btn-primary" data-action="navigate" data-page="search">Find equipment</button></div>`}</div></div><div class="card"><div class="panel-head"><div><h2>Control checks</h2><p>Guardrails for an engineering calculation</p></div><span class="tag ${state.records.length || state.mode === "demo" ? "green" : "amber"}">${state.records.length || state.mode === "demo" ? "Ready to review" : "Awaiting source"}</span></div><div class="panel-body"><div class="check-list"><div class="check-line"><span class="tag green">✓</span><span>Price magnitude is excluded from source ranking.</span></div><div class="check-line"><span class="tag green">✓</span><span>Similar records cannot be added as estimate bases.</span></div><div class="check-line"><span class="tag amber">!</span><span>Country factor is unadjusted until an approved factor is supplied.</span></div><div class="check-line"><span class="tag green">✓</span><span>Source file, hash, sheet, row, cell and formula lineage carry into export.</span></div></div></div></div></div>`; }

function dynamicFilterOptions(field, selected) { const labels = { voltage: "Any voltage", rating: "Any rating", manufacturer: "Any manufacturer", country: "Any country" }; const values = [...new Set(currentRecords().map((record) => field === "country" ? record.country : record.attributes?.[field]).filter(Boolean))].sort(); return [labels[field], ...values].map((value) => `<option value="${esc(value)}" ${value === selected ? "selected" : ""}>${esc(value)}</option>`).join(""); }
function resultCard(result, similar = false) { const record = result.record; const specs = Object.entries(record.attributes || {}).filter(([key]) => key !== "equipmentType").slice(0, 4).map(([key, value]) => `${key}: ${value}`).join(" · "); const basis = safeBasis(record); const selectable = !similar && result.matchClass !== "Similar / closest available"; return `<div class="result-card ${similar ? "similar" : ""}"><div><span class="match ${similar ? "similar" : "exact"}">${esc(result.matchClass)}</span><div class="result-score mono">${result.score}/100</div></div><div><div class="result-key">${esc(record.description)}</div><div class="td-sub">${esc(record.sourceProject)} · ${esc(record.sheet)}!${esc(record.cell || record.row)}</div></div><div class="result-spec">${esc(specs)}<br/><span class="tag">${esc(record.recordType || "Historical price record")}</span></div><div><div class="result-price">${basis === null ? "Review" : formatMoney(basis, 0, record.currency)}</div><div class="result-year">${esc(record.year)} · ${esc(record.currency || "Unknown currency")} · ${esc(record.country)}</div></div><div><span class="quality ${qualityClass(record.quality)}">${esc(record.quality)}</span><div class="td-sub">${esc((result.differences?.[0] || record.qualityReason || "Source lineage available")).slice(0, 72)}</div></div><div class="result-actions"><button class="row-action" data-action="view-source" data-id="${esc(record.id)}">Inspect source</button>${selectable ? `<button class="btn btn-sm btn-primary" data-action="open-builder" data-id="${esc(record.id)}" data-match-class="${esc(result.matchClass)}">Select source basis</button>` : `<span class="tiny muted">Comparison only</span>`}</div></div>`; }
function renderSearch() { const results = currentResults(); const exact = results.filter((result) => result.matchClass !== "Similar / closest available"); const similar = results.filter((result) => result.matchClass === "Similar / closest available"); const types = ["All equipment", ...new Set(currentRecords().map((record) => record.attributes?.equipmentType).filter(Boolean))].sort(); return pageHead("Evidence first", "Equipment search", "Search committed source rows. Match quality, technical differences and source lineage are visible before selection.", `<button class="btn" data-action="navigate" data-page="databases">Manage databases</button><button class="btn btn-primary" data-action="navigate" data-page="estimate">View estimate (${state.items.length})</button>`) + sourceNotice() + `<div class="search-bar"><input class="input search-input" data-field="search-query" value="${esc(state.filters.query)}" placeholder="Search description, type, voltage, rating…"/><select class="select" data-field="equipmentType">${typeOptions(types, state.filters.equipmentType)}</select><select class="select" data-field="voltage">${dynamicFilterOptions("voltage", state.filters.voltage)}</select><select class="select" data-field="rating">${dynamicFilterOptions("rating", state.filters.rating)}</select><button class="btn btn-primary" data-action="apply-search">Search</button><button class="btn" data-action="clear-filters">Clear</button></div><div class="filter-strip"><span class="filter-label">Additional filters</span><select class="select" data-field="manufacturer">${dynamicFilterOptions("manufacturer", state.filters.manufacturer)}</select><select class="select" data-field="country">${dynamicFilterOptions("country", state.filters.country)}</select><span class="tag">${results.length} records scored</span><span class="tag">Ranking excludes price magnitude</span></div><div class="card card-pad"><div class="panel-head compact"><div><h2>Historical source comparison</h2><p>Exact and strong technical matches can be inspected and selected. Similar records are comparison-only.</p></div><span class="mono tiny muted">${dateLabel()}</span></div>${!currentRecords().length ? `<div class="empty-state"><div class="empty-icon">⌕</div><h3>No searchable production rows</h3><p>Import a workbook and approve its mapping before source records appear here.</p><button class="btn btn-primary" data-action="navigate" data-page="databases">Import workbook</button><button class="btn" data-action="enable-demo">Use training demo</button></div>` : `${exact.length ? `<div class="result-group"><div class="result-group-head"><div class="result-group-title"><h3>Exact / strong matches</h3><span>${exact.length} source${exact.length === 1 ? "" : "s"}</span></div><span class="tag green">Eligible for review</span></div>${exact.map((result) => resultCard(result)).join("")}</div>` : `<div class="no-results">No exact or strong source record was found for the current filters.</div>`}${similar.length ? `<div class="result-group" style="margin-bottom:0"><div class="similar-banner">Similar records are actual source rows with one or more differences. They cannot become an estimate line.</div><div class="result-group-head"><div class="result-group-title"><h3>Similar / closest available</h3><span>${similar.length} source${similar.length === 1 ? "" : "s"}</span></div><span class="tag amber">Comparison only</span></div>${similar.map((result) => resultCard(result, true)).join("")}</div>` : ""}`}</div>`; }

function componentDisplay(component) { if (["percentage", "percentage_rate"].includes(component.componentType)) return `${(Number(component.rawValue) * 100).toFixed(2)}%`; if (["multiplier", "cumulative_factor"].includes(component.componentType)) return `${Number(component.rawValue).toFixed(4)} ×`; return `${formatNumber(component.rawValue, 4)} ${component.currency || ""}`.trim(); }
function renderTrace(record) { const rawValues = (record.rawValues || []).slice(0, 8); return `<div class="card trace-card"><div class="trace-hero"><div class="eyebrow">Selected historical source</div><h2>${esc(record.description)}</h2><p>${esc(record.sourceProject)} · ${esc(record.currency || "Unknown currency")}</p></div><div class="trace-body"><div class="detail-list"><div class="detail-item"><label>Database / revision</label><div>${esc(record.database)} · <span class="mono">${esc(record.revision)}</span></div></div><div class="detail-item"><label>Workbook hash</label><div class="mono">${esc(record.databaseId || "Not available")}</div></div><div class="detail-item"><label>Worksheet / cell</label><div>${esc(record.sheet)} · <span class="mono">${esc(record.cell || record.row)}</span></div></div><div class="detail-item"><label>Source reference</label><div class="mono">${esc(record.reference)}</div></div><div class="detail-item"><label>Source project / supplier</label><div>${esc(record.sourceProject)} · ${esc(record.supplier)}</div></div><div class="detail-item"><label>Price year / country / unit</label><div>${esc(record.year)} · ${esc(record.country)} · ${esc(record.unit || "per unit")}</div></div></div><div class="section-title"><h3>Technical specification</h3></div><div class="detail-list">${Object.entries(record.attributes || {}).map(([key, value]) => `<div class="detail-item"><label>${esc(key.replace(/([A-Z])/g, " $1"))}</label><div>${esc(value)}</div></div>`).join("")}</div><div class="section-title"><h3>Raw source cells</h3></div><div class="source-cells">${rawValues.length ? rawValues.map((value) => `<div><span class="mono">${esc(value.cell)}</span><span>${esc(value.heading)}: ${esc(value.rawValue)}</span>${value.formula ? `<code>${esc(value.formula)}</code>` : ""}</div>`).join("") : `<div class="muted tiny">Cell-level evidence is not available for this fixture.</div>`}</div></div><div class="trace-footer"><p><strong>Quality: ${esc(record.quality || "Review")}</strong> · ${esc(record.qualityReason || "Review source semantics before use.")}</p></div></div>`; }
function defaultBuilderSettings(record) { return { targetYear: Number.isInteger(Number(record.year)) ? state.project.targetYear : Number(record.year) || state.project.targetYear, method: Number(record.sourceFactor) > 0 ? "source" : "none", indexId: DEMO_INDEX_CATALOGUE[0].id, annualRate: 0.04, locationFactor: 1, quantity: 1, components: {} }; }
function builderSettings() { return state.builder?.settings || defaultBuilderSettings(currentRecords().find((record) => record.id === state.builder?.recordId) || DEMO_RECORDS[0]); }
function renderBuilder() { if (!state.builder) return renderSearch(); const record = currentRecords().find((item) => item.id === state.builder.recordId); if (!record) return renderSearch(); const settings = builderSettings(); const calc = safeCalculate(record, settings); const methods = [["none", "No escalation", "Retain the source-year basis."], ["annual", "Annual assumption", "Future assumption entered by the engineer."]]; if (state.mode === "demo") methods.unshift(["index", "Published index", "Illustrative demo index; never available in production mode."]); if (Number(record.sourceFactor) > 0) methods.unshift(["source", "Source-workbook factor", "Use only after formula semantics are approved."]); return pageHead("Transparent build-up", "Price builder", "Select components, escalation and quantity explicitly. A similar record can be inspected but cannot be added as a source basis.", `<button class="btn" data-action="navigate" data-page="search">Back to results</button><button class="btn btn-primary" data-action="add-estimate" ${state.builder.matchClass === "Similar / closest available" ? "disabled" : ""}>Add source basis</button>`) + sourceNotice() + `<div class="builder-grid"><div>${renderTrace(record)}</div><div class="card"><div class="builder-section"><div class="builder-section-head"><div><h3>Source cost components</h3><p>Unknown or unresolved components stay excluded until reviewed.</p></div><span class="tag">${calc.amounts.filter((component) => component.included).length} included</span></div><div class="table-wrap"><table class="component-table"><thead><tr><th></th><th>Component</th><th>Source value</th><th>Semantics</th><th>Applied</th></tr></thead><tbody>${(record.components || []).map((component) => `<tr><td><input class="component-toggle" type="checkbox" data-component="${esc(component.id)}" ${(settings.components[component.id] ?? component.includedByDefault) ? "checked" : ""} ${component.componentType === "unknown" ? "disabled" : ""}/></td><td><div class="component-name">${esc(component.name)}</div><div class="component-note">${esc(component.note || "")}</div></td><td class="mono">${esc(componentDisplay(component))}</td><td><div class="component-type">${esc(component.componentType.replaceAll("_", " "))}</div><div class="component-note">Base: ${esc(component.calculationBase || "declared source base")}</div></td><td class="mono">${formatMoney((calc.amounts.find((amount) => amount.id === component.id)?.amount || 0), 2, record.currency)}</td></tr>`).join("")}</tbody></table></div></div><div class="builder-section"><div class="builder-section-head"><div><h3>Escalation / inflation</h3><p>Observed source factors, approved indices and future assumptions are kept distinct.</p></div><span class="tag amber">${esc(calc.escalation.label || "Review")}</span></div><div class="radio-row">${methods.map(([id, title, copy]) => `<div class="radio-card"><input id="method-${id}" name="method" type="radio" value="${id}" data-field="builder-method" ${settings.method === id ? "checked" : ""}/><label for="method-${id}"><span class="radio-title">${esc(title)}</span><span class="radio-copy">${esc(copy)}</span></label></div>`).join("")}</div>${settings.method === "index" ? `<div class="form-grid" style="margin-top:12px"><div class="field"><label>Demo index catalogue</label><select class="select" data-field="builder-index">${DEMO_INDEX_CATALOGUE.map((index) => `<option value="${esc(index.id)}" ${index.id === settings.indexId ? "selected" : ""}>${esc(index.name)}</option>`).join("")}</select></div><div class="formula-box">${esc(calc.escalation.basis || "Index ratio")}</div></div>` : ""}${settings.method === "annual" ? `<div class="form-grid" style="margin-top:12px"><div class="field"><label>Future annual assumption</label><div class="unit-input"><input class="input" type="number" min="0" max="1" step="0.001" data-field="builder-annual" value="${Number(settings.annualRate)}"/><span>decimal</span></div></div><div class="formula-box">${esc(calc.escalation.basis || "Future assumption only")}</div></div>` : ""}<div class="formula-box" style="margin-top:12px"><strong>Applied factor ${Number(calc.escalation.factor || 1).toFixed(4)} ×</strong><br/>${esc(calc.escalation.basis || "No escalation")}</div></div><div class="builder-section"><div class="builder-section-head"><div><h3>Country / location adjustment</h3><p>${esc(record.country)} → ${esc(state.project.country)}</p></div><span class="tag amber">Unadjusted</span></div><div class="form-grid"><div class="field"><label>Applied factor</label><div class="unit-input"><input class="input" type="number" min="0.0001" step="0.0001" data-field="builder-location" value="${Number(settings.locationFactor).toFixed(4)}"/><span>×</span></div></div><div class="formula-box">${esc(LOCATION_FACTOR_POLICY.rationale)}<br/><strong>Unadjusted — country factor unavailable</strong></div></div></div><div class="builder-section"><div class="builder-section-head"><div><h3>Target-year result</h3><p>${calc.error ? `Calculation blocked: ${calc.error}` : "Fixed-point arithmetic; display is rounded only at the boundary."}</p></div></div><div class="form-grid"><div class="field"><label>Target cost year</label><input class="input" type="number" min="1900" max="2200" data-field="builder-target-year" value="${esc(settings.targetYear)}"/></div><div class="field"><label>Quantity</label><input class="input" type="number" min="0" step="1" data-field="builder-quantity" value="${esc(settings.quantity)}"/></div></div><div class="calc-strip" style="margin-top:16px"><div><div class="calc-label">Historical basis</div><div class="calc-value">${formatMoney(calc.historicalBasis, 0, record.currency)}</div><div class="calc-foot">Included components</div></div><div><div class="calc-label">Escalation</div><div class="calc-value">${Number(calc.escalation.factor || 1).toFixed(4)}×</div><div class="calc-foot">${esc(record.year)} → ${esc(settings.targetYear)}</div></div><div><div class="calc-label">Unit cost</div><div class="calc-value">${formatMoney(calc.targetUnitCost, 0, record.currency)}</div><div class="calc-foot">Location ${Number(calc.locationFactor || 0).toFixed(4)}×</div></div><div><div class="calc-label">Line total</div><div class="calc-value accent">${formatMoney(calc.total, 0, record.currency)}</div><div class="calc-foot">× ${formatNumber(calc.quantity, 0)} unit${calc.quantity === 1 ? "" : "s"}</div></div></div><div class="builder-actions"><button class="btn" data-action="view-source" data-id="${esc(record.id)}">Inspect source detail</button><button class="btn btn-primary" data-action="add-estimate" ${calc.error || state.builder.matchClass === "Similar / closest available" ? "disabled" : ""}>Add source basis</button></div></div></div></div>`; }

function renderEstimate() { const { rows, direct, indirect, total } = totals(); return pageHead("Decision-ready estimate", "Project cost estimate", "Review selected source rows, edit quantities and apply only documented project-level costs.", `<button class="btn" data-action="new-revision">Snapshot revision</button><button class="btn btn-primary" data-action="export">Export XLSX</button>`) + `<div class="estimate-head"><div class="project-context"><div class="eyebrow">Active project · Rev ${state.revisions.length}</div><h2>${esc(state.project.name)}</h2><p>${esc(state.project.number)} · ${esc(state.project.client)}</p><div class="context-meta"><div><label>Target country</label><span>${esc(state.project.country)}</span></div><div><label>Target cost year</label><span>${esc(state.project.targetYear)}</span></div><div><label>Currency</label><span>${esc(state.project.currency)}</span></div></div><div class="editable-context"><div class="form-grid"><div class="field"><label>Project name</label><input class="input" data-field="project-name" value="${esc(state.project.name)}"/></div><div class="field"><label>Target country</label><input class="input" data-field="project-country" value="${esc(state.project.country)}"/></div><div class="field"><label>Target cost year</label><input class="input" type="number" data-field="project-target-year" value="${esc(state.project.targetYear)}"/></div><div class="field"><label>Project number</label><input class="input" data-field="project-number" value="${esc(state.project.number)}"/></div></div></div></div><div class="total-card"><div class="metric-label">Current estimate total</div><div class="total-big">${total ? formatMoney(total, 0, state.project.currency) : "—"}</div><div class="total-sub">${rows.length} equipment line${rows.length === 1 ? "" : "s"} · ${formatMoney(indirect, 0, state.project.currency)} indirect costs</div></div></div><div class="section-title"><h2>Equipment estimate</h2><span class="muted tiny">${rows.length ? "Selected source lineage retained" : "Add a source from Equipment search"}</span></div><div class="card">${rows.length ? `<div class="table-wrap"><table><thead><tr><th>Item</th><th>Specification</th><th>Qty</th><th>Source basis</th><th>Escalation</th><th>Adjusted unit</th><th>Total</th><th></th></tr></thead><tbody>${rows.map((row, index) => `<tr><td><div class="td-strong">${index + 1}. ${esc(row.record.attributes?.equipmentType)}</div><div class="td-sub">${esc(row.record.description)}</div><div class="td-sub"><span class="tag ${row.matchClass === "Strong technical match" ? "amber" : "green"}">${esc(row.matchClass || "Selected source")}</span></div></td><td>${esc(row.record.attributes?.voltage || "—")}<div class="td-sub">${esc(row.record.attributes?.rating || "")}</div></td><td><input class="input cost-input" type="number" min="0" step="1" data-item-qty="${esc(row.id)}" value="${esc(row.calc.quantity)}"/></td><td><div class="td-strong">${formatMoney(row.calc.historicalBasis, 0, row.record.currency)}</div><div class="td-sub">${esc(row.record.year)} · ${esc(row.record.reference)}</div></td><td><div class="mono">${Number(row.calc.escalation.factor || 1).toFixed(4)}×</div><div class="td-sub">${esc(row.calc.escalation.label || "Blocked")}</div></td><td class="td-strong">${formatMoney(row.calc.targetUnitCost, 0, row.record.currency)}</td><td class="td-strong">${formatMoney(row.calc.total, 0, row.record.currency)}</td><td><button class="row-action" data-action="remove-item" data-item="${esc(row.id)}">Remove</button></td></tr>`).join("")}</tbody><tfoot><tr><td colspan="6" style="text-align:right;font-weight:800">Direct equipment total</td><td style="font-weight:800">${formatMoney(direct, 0, state.project.currency)}</td><td></td></tr></table></div>` : `<div class="empty-state"><div class="empty-icon">▤</div><h3>Your estimate is empty</h3><p>Search the committed source register and select an exact or strong source record.</p><button class="btn btn-primary" data-action="navigate" data-page="search">Search source register</button></div>`}</div><div class="section-title"><h2>Project-level indirect costs</h2><span class="muted tiny">No percentages are pre-populated without a source basis</span></div><div class="estimate-layout"><div class="card card-pad"><div class="panel-head compact"><div><h3>Optional additions</h3><p>Percentage inputs are points, e.g. 5.00 = 5%.</p></div></div>${state.indirectCosts.map((item) => `<div class="cost-row"><div><div class="cost-name"><input type="checkbox" data-indirect-toggle="${item.id}" ${item.enabled ? "checked" : ""}/> ${esc(item.name)}</div><div class="cost-basis">Basis: ${esc(item.basis)} · ${esc(item.rationale)}</div></div><div class="inline-input"><input class="input cost-input" type="number" min="0" step="0.01" data-indirect-value="${item.id}" value="${item.type === "percent" ? (Number(item.applied) * 100).toFixed(2) : Number(item.applied).toFixed(2)}"/><span class="muted tiny">${item.type === "percent" ? "%" : state.project.currency}</span></div></div>`).join("")}</div><div class="side-stack"><div class="card card-pad"><h3>Reconciliation</h3><div class="summary-line"><span>Direct equipment total</span><strong>${formatMoney(direct, 0, state.project.currency)}</strong></div><div class="summary-line"><span>Enabled indirect costs</span><strong>${formatMoney(indirect, 0, state.project.currency)}</strong></div><div class="summary-line total"><span>Estimate total</span><strong>${formatMoney(total, 0, state.project.currency)}</strong></div></div><div class="card card-pad"><h3>Calculation chain</h3><div class="formula-box"><strong>Selected components</strong><br/>→ historical basis<br/>→ approved/explicit escalation<br/>→ unadjusted or approved country factor<br/>→ unit cost × quantity<br/>→ direct total + optional indirect costs</div></div></div></div>`; }

function importSteps() { return ["Select", "Analyse", "Mapping", "Validation", "Preview", "Import"]; }
function renderImportWizard() { const steps = importSteps(); const pending = state.pendingImport; const analysis = pending?.analysis; const validation = pending?.validation; const stepBar = `<div class="wizard-steps">${steps.map((step, index) => `<div class="wizard-step ${state.importStage === index ? "current" : state.importStage > index ? "done" : ""}"><span>${String(index + 1).padStart(2, "0")}</span>${step}</div>`).join("")}</div>`; if (!pending) return `<div class="upload-box"><div class="upload-icon">⇧</div><h3>Analyse a workbook locally</h3><p>Supported: XLSX, XLSM, XLSB and legacy XLS. Maximum ${Math.round(MAX_WORKBOOK_BYTES / 1024 / 1024)} MB. Macros and embedded code are never executed, and workbook bytes are never uploaded.</p><button class="btn btn-primary" data-action="choose-file">Choose workbook</button><div class="upload-meta">${PARSER_VERSION} · SHA-256 fingerprint · IndexedDB after approval</div>${state.lastImport ? `<div class="success-line"><strong>Last import:</strong> ${esc(state.lastImport)}</div>` : ""}${state.importError ? `<div class="error-text" role="alert">${esc(state.importError)}</div>` : ""}</div>`; if (state.importStage === 1) return `${stepBar}<div class="card card-pad"><div class="panel-head compact"><div><h2>Workbook analysed</h2><p>${esc(pending.fileMeta.fileName)} · ${formatNumber(pending.fileMeta.size / 1024, 1)} KB · <span class="mono">${esc(pending.fileMeta.hash)}</span></p></div><span class="tag green">Local parse complete</span></div><div class="grid grid-3"><div class="stat-box"><span>Worksheets</span><strong>${analysis.sheets.length}</strong></div><div class="stat-box"><span>Candidate source rows</span><strong>${analysis.recordCount}</strong></div><div class="stat-box"><span>Formula cells retained</span><strong>${analysis.formulasDetected ? "Detected" : "None detected"}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Worksheet</th><th>Classification</th><th>Meaningful range</th><th>Headers</th><th>Confidence</th></tr></thead><tbody>${analysis.sheets.map((sheet) => `<tr><td>${esc(sheet.name)}${sheet.hidden ? " · hidden" : ""}</td><td>${esc(sheet.classification)}</td><td class="mono">${sheet.range.rows.length ? `${sheet.range.startRow + 1}:${sheet.range.endRow + 1} · ${sheet.range.nonEmptyCells} cells` : "empty"}</td><td>${sheet.headerCandidates.length}</td><td>${Math.round(sheet.confidence * 100)}%</td></tr>`).join("")}</tbody></table></div><div class="wizard-actions"><button class="btn" data-action="cancel-import">Discard analysis</button><button class="btn btn-primary" data-action="import-next">Review mapping</button></div></div>`; if (state.importStage === 2) return `${stepBar}<div class="card card-pad"><div class="panel-head compact"><div><h2>Review mapping</h2><p>Pattern-driven proposals use labels, value profiles and repeated price columns. Confirm candidate source sheets before validation.</p></div><span class="tag amber">Human review required</span></div><div class="mapping-list">${analysis.sheets.map((sheet) => `<div class="mapping-card"><div><strong>${esc(sheet.name)}</strong><span class="tag">${esc(sheet.classification)}</span><div class="td-sub">Meaningful range: ${sheet.range.rows.length ? `${sheet.range.startRow + 1}:${sheet.range.endRow + 1}` : "empty"} · ${sheet.range.nonEmptyCells} populated cells</div></div><div class="mapping-fields">${Object.entries(sheet.mapping).slice(0, 8).map(([field, label]) => `<div><span>${esc(field)}</span><strong>${esc(label)}</strong></div>`).join("") || `<span class="muted tiny">No canonical headers proposed</span>`}</div><label class="mapping-check"><input type="checkbox" data-map-sheet="${esc(sheet.name)}" ${analysis.priceSheets.includes(sheet.name) ? "checked" : ""}/> Use for historical price extraction</label></div>`).join("")}</div><div class="wizard-actions"><button class="btn" data-action="cancel-import">Discard analysis</button><button class="btn btn-primary" data-action="import-next">Accept mapping & validate</button></div></div>`; if (state.importStage === 3) return `${stepBar}<div class="card card-pad"><div class="panel-head compact"><div><h2>Validation</h2><p>Blocking errors must be resolved before any source row can be committed.</p></div><span class="tag ${validation.canImport ? "green" : "red"}">${validation.canImport ? "Pass with review warnings" : "Blocked"}</span></div><div class="validation-list">${validation.issues.map((issue) => `<div class="validation-item error"><span>×</span><div><strong>${esc(issue.severity)}</strong><p>${esc(issue.message)}</p></div></div>`).join("")}${validation.warnings.map((warning) => `<div class="validation-item warning"><span>!</span><div><strong>Warning</strong><p>${esc(warning)}</p></div></div>`).join("")}${!validation.issues.length && !validation.warnings.length ? `<div class="validation-item success"><span>✓</span><div><strong>Validation passed</strong><p>No blocking issues were detected.</p></div></div>` : ""}</div><div class="wizard-actions"><button class="btn" data-action="back-import">Back to mapping</button><button class="btn btn-primary" data-action="import-next" ${validation.canImport ? "" : "disabled"}>Review preview</button></div></div>`; if (state.importStage === 4) return `${stepBar}<div class="card card-pad"><div class="panel-head compact"><div><h2>Preview before commit</h2><p>${analysis.recordCount} rows will be stored as a local database. Original workbook bytes are discarded after parsing; source hashes and cell evidence remain.</p></div><span class="tag green">No commit yet</span></div><div class="table-wrap"><table><thead><tr><th>Description</th><th>Equipment type</th><th>Source cell</th><th>Price</th><th>Year / currency</th><th>Quality</th></tr></thead><tbody>${analysis.records.slice(0, 30).map((record) => `<tr><td>${esc(record.description)}</td><td>${esc(record.attributes.equipmentType)}</td><td class="mono">${esc(record.sheet)}!${esc(record.cell)}</td><td>${esc(record.components[0]?.rawValue)} ${esc(record.currency)}</td><td>${esc(record.year)} · ${esc(record.currency)}</td><td><span class="quality ${qualityClass(record.quality)}">${esc(record.quality)}</span></td></tr>`).join("")}</tbody></table></div>${analysis.records.length > 30 ? `<p class="tiny muted">Showing first 30 rows of ${analysis.records.length}; all validated rows will be committed.</p>` : ""}<div class="wizard-actions"><button class="btn" data-action="back-import">Back to validation</button><button class="btn btn-primary" data-action="commit-import">Import ${analysis.recordCount} source rows</button></div></div>`; return `${stepBar}<div class="card card-pad"><div class="success-panel"><div class="success-icon">✓</div><h2>Database imported locally</h2><p>${esc(pending.database.name)} is now available in production search. Source lineage and validation metadata are retained in IndexedDB.</p><button class="btn btn-primary" data-action="finish-import">Open equipment search</button><button class="btn" data-action="navigate" data-page="databases">Review databases</button></div></div>`; }

function renderDatabases() { return pageHead("Controlled source register", "Databases", "Import source workbooks through a reviewable local pipeline. No source bytes leave this browser.", `<button class="btn btn-primary" data-action="choose-file">Upload database</button>`) + sourceNotice() + renderImportWizard() + `<div class="card"><div class="panel-head"><div><h2>Source database inventory</h2><p>Only committed revisions appear in production search. Toggle visibility without changing the immutable source revision.</p></div><span class="tag">${state.databases.length} registered</span></div>${state.databases.length ? state.databases.map((db) => `<div class="database-row"><div><div class="file-name">${esc(db.name)}</div><div class="file-sub">${esc(db.source)} · <span class="mono">${esc(db.hash?.slice(0, 18))}…</span></div></div><div><div class="tiny muted">Revision</div><div class="mono tiny">${esc(db.revision)}</div></div><div><div class="tiny muted">Rows</div><div class="td-strong">${db.recordsCount ?? db.records?.length ?? 0}</div></div><div><div class="tiny muted">Sources</div><div class="td-strong">${db.sources ?? 0}</div></div><div><span class="status ${db.enabled === false ? "paused" : "active"}">${db.enabled === false ? "Disabled" : "Enabled"}</span><div class="file-sub">${esc(db.visibility || "Private local workspace")}</div></div><div><button class="row-action" data-action="toggle-db" data-id="${esc(db.id)}">${db.enabled === false ? "Enable" : "Disable"}</button></div></div>`).join("") : `<div class="empty-state compact-empty"><h3>No committed source databases</h3><p>Import one of the named FAR/price workbooks when available. They are intentionally not included in the public repository.</p><button class="btn" data-action="enable-demo">Use training demo</button></div>`}</div><div class="grid grid-2" style="margin-top:16px"><div class="card card-pad"><h3>Import guardrails</h3><div class="check-list"><div class="check-line"><span class="tag green">01</span><span>Hash and parse locally with a pinned XLSX/XLSM/XLSB/XLS adapter.</span></div><div class="check-line"><span class="tag green">02</span><span>Detect meaningful ranges rather than trusting phantom worksheet dimensions.</span></div><div class="check-line"><span class="tag green">03</span><span>Preserve raw values, formulas, source cells and repeated historical columns.</span></div><div class="check-line"><span class="tag green">04</span><span>Require mapping, validation and preview before commit.</span></div></div></div><div class="card card-pad"><h3>Parser and privacy</h3><p class="muted tiny">${PARSER_VERSION}. Macro metadata is flagged but not retained or executed. Formula cached values are read as source evidence; formulas are preserved for traceability, not recalculated.</p><div class="citation">${esc(storageDescription())}. GitHub Pages is a static public host, so confidential workbooks must stay on the engineer’s device.</div></div></div>`; }
function renderExisting() { return pageHead("Valuation mode", "Existing asset valuation", "Keep existing-asset/FAR valuation separate from historical price search. This module remains gated until the supplied FAR methods are audited and reproduced.", `<button class="btn" data-action="navigate" data-page="databases">Review source data</button>`) + notice("No verified FAR workbook has been imported. Replacement-cost, useful-life and depreciated replacement-cost values are not generated, and no placeholder assets are shown.", "Existing asset valuation is under validation", "warning") + `<div class="card gate-card"><div class="gate-icon">◈</div><h2>FAR method gate is closed</h2><p>When a verified FAR is available, this page will show imported asset identity, station hierarchy, dynamic technical attributes, commissioning year, useful life, condition evidence, replacement value, residual life and source formulas. A generic straight-line method will not be substituted.</p><div class="gate-grid"><div><strong>Pending evidence</strong><span>Transmission FAR workbook</span></div><div><strong>Pending evidence</strong><span>Generating Stations FAR workbook</span></div><div><strong>Pending method audit</strong><span>Useful-life and DCRV formulas</span></div></div></div>`; }
function renderBasis() { const { rows, direct, indirect, total } = totals(); const sheets = ["01_Estimate_Summary", "02_Equipment_Estimate", "03_Cost_Breakdown", "04_Inflation_Escalation", "05_Country_Adjustments", "06_Source_Register", "07_Assumptions", "08_Alternative_Matches", "09_Basis_of_Estimate"]; return pageHead("Governance", "Basis & export", "Review the calculation chain, source limitations and export package before sharing an estimate.", `<button class="btn btn-primary" data-action="export">Export XLSX</button>`) + sourceNotice() + `<div class="grid grid-3"><div class="card metric"><div class="metric-label">Direct total</div><div class="metric-value">${formatMoney(direct, 0, state.project.currency)}</div><div class="metric-meta">${rows.length} selected lines</div></div><div class="card metric"><div class="metric-label">Indirect total</div><div class="metric-value">${formatMoney(indirect, 0, state.project.currency)}</div><div class="metric-meta">Explicit user inputs only</div></div><div class="card metric"><div class="metric-label">Export package</div><div class="metric-value">9</div><div class="metric-meta">Traceability worksheets</div></div></div><div class="grid grid-2" style="margin-top:16px"><div class="card card-pad"><h2>Calculation chain</h2><div class="formula-box"><strong>Component graph</strong><br/>→ historical basis in source currency<br/>→ explicit escalation method<br/>→ unadjusted or approved location factor<br/>→ quantity<br/>→ direct equipment total + optional indirect costs<br/><br/><span class="muted">Current total: ${formatMoney(total, 0, state.project.currency)}</span></div></div><div class="card card-pad"><h2>Workbook export</h2><p class="muted">The export is a new sanitized XLSX. It never embeds the original macro-enabled or binary workbook.</p><div class="sheet-list">${sheets.map((sheet) => `<div><span class="tag">${sheet.slice(0, 2)}</span><span>${sheet.slice(3)}</span></div>`).join("")}</div></div></div>`; }
function renderSettings() { return pageHead("Governance", "Settings", "Control local data mode, privacy boundaries and calculation defaults.", "") + `<div class="grid grid-2"><div class="card card-pad"><h2>Data mode</h2><p class="muted">Production mode searches only imported, committed workbooks. Training demo mode is explicit and visibly marked.</p><div class="mode-row"><button class="btn ${state.mode === "production" ? "btn-primary" : ""}" data-action="production-mode">Production mode</button><button class="btn ${state.mode === "demo" ? "btn-warning" : ""}" data-action="enable-demo">Use training demo</button></div><div class="citation">${state.mode === "demo" ? esc(DEMO_DATA_NOTICE) : "No illustrative records are active."}</div></div><div class="card card-pad"><h2>Privacy and storage</h2><div class="check-list"><div class="check-line"><span class="tag green">Local</span><span>${esc(storageDescription())}</span></div><div class="check-line"><span class="tag green">No upload</span><span>Workbook bytes are read from the file picker only.</span></div><div class="check-line"><span class="tag green">No macros</span><span>VBA and embedded code are never executed.</span></div><div class="check-line"><span class="tag amber">Public host</span><span>Do not put confidential source files in this GitHub repository.</span></div></div></div></div>`; }
function renderModal() { if (state.modal?.type !== "source") return ""; const record = [...DEMO_RECORDS, ...state.records].find((item) => item.id === state.modal.id); return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" data-modal-content role="dialog" aria-modal="true" aria-label="Source details"><div class="modal-head"><div><div class="eyebrow">Source drawer</div><h2>${esc(record?.description || "Source not found")}</h2></div><button class="modal-close" aria-label="Close source details" data-action="close-modal">×</button></div>${record ? renderTrace(record) : `<p class="muted">This source is no longer enabled.</p>`}</div></div>`; }
function render() { if (!state.ready) { app.innerHTML = `<div class="loading-screen"><div class="brand-mark">AV</div><h1>Loading local workspace</h1><p>Opening browser-local database…</p></div>`; return; } const content = state.page === "dashboard" ? renderDashboard() : state.page === "search" ? renderSearch() : state.page === "builder" ? renderBuilder() : state.page === "estimate" ? renderEstimate() : state.page === "databases" ? renderDatabases() : state.page === "existing" ? renderExisting() : state.page === "basis" ? renderBasis() : renderSettings(); app.innerHTML = layout(content); }

function openBuilder(id, matchClass = "Exact source match") { const record = currentRecords().find((item) => item.id === id); if (!record || matchClass === "Similar / closest available") return showToast("Similar records are comparison-only and cannot be selected."); const existing = state.items.find((item) => item.record.id === id); state.builder = { recordId: id, matchClass, settings: existing ? { ...existing.settings, targetYear: state.project.targetYear } : defaultBuilderSettings(record) }; state.page = "builder"; state.modal = null; render(); }
function addEstimate() { if (!state.builder || state.builder.matchClass === "Similar / closest available") return showToast("A similar record cannot become an estimate basis."); const record = currentRecords().find((item) => item.id === state.builder.recordId); if (!record) return; const settings = structuredClone(state.builder.settings); settings.targetYear = Number(settings.targetYear) || state.project.targetYear; settings.quantity = Math.max(0, Number(settings.quantity) || 0); try { calculatePrice(record, settings); } catch (error) { return showToast(`Cannot add line: ${error.message}`); } const id = `item-${record.id}`; const existing = state.items.find((item) => item.id === id); if (existing) Object.assign(existing, { settings, matchClass: state.builder.matchClass, differences: state.builder.differences || [] }); else state.items.push({ id, record, settings, matchClass: state.builder.matchClass, differences: state.builder.differences || [] }); state.page = "estimate"; state.builder = null; persist(); showToast(existing ? "Estimate line updated" : "Source basis added to estimate"); }
function updateBuilder(next) { if (!state.builder) return; state.builder.settings = { ...state.builder.settings, ...next }; render(); }
function handleInput(event) { const field = event.target.dataset.field; const indirectValue = event.target.dataset.indirectValue; if (indirectValue) { const item = state.indirectCosts.find((entry) => entry.id === indirectValue); if (item) item.applied = item.type === "percent" ? (Number(event.target.value) || 0) / 100 : Number(event.target.value) || 0; persist(); return; } if (!field) return; if (field === "search-query") { state.filters.query = event.target.value; return; } if (["equipmentType", "voltage", "rating", "manufacturer", "country"].includes(field)) { state.filters[field] = event.target.value; render(); return; } if (field === "builder-target-year") updateBuilder({ targetYear: Number(event.target.value) || state.project.targetYear }); else if (field === "builder-quantity") updateBuilder({ quantity: Math.max(0, Number(event.target.value) || 0) }); else if (field === "builder-location") updateBuilder({ locationFactor: Math.max(0, Number(event.target.value) || 0) }); else if (field === "builder-annual") updateBuilder({ annualRate: Math.max(0, Number(event.target.value) || 0) }); else if (field === "builder-index") updateBuilder({ indexId: event.target.value }); else if (field === "project-name") { state.project.name = event.target.value; persist(); } else if (field === "project-number") { state.project.number = event.target.value; persist(); } else if (field === "project-country") { state.project.country = event.target.value; persist(); } else if (field === "project-target-year") { state.project.targetYear = Number(event.target.value) || 2030; persist(); } }
function handleChange(event) { const field = event.target.dataset.field; if (field === "builder-method") updateBuilder({ method: event.target.value }); const componentId = event.target.dataset.component; if (componentId) updateBuilder({ components: { ...builderSettings().components, [componentId]: event.target.checked } }); const itemQty = event.target.dataset.itemQty; if (itemQty) { const item = state.items.find((entry) => entry.id === itemQty); if (item) item.settings.quantity = Math.max(0, Number(event.target.value) || 0); persist(); render(); } const indirectToggle = event.target.dataset.indirectToggle; if (indirectToggle) { const item = state.indirectCosts.find((entry) => entry.id === indirectToggle); if (item) item.enabled = event.target.checked; persist(); render(); } const indirectValue = event.target.dataset.indirectValue; if (indirectValue) { const item = state.indirectCosts.find((entry) => entry.id === indirectValue); if (item) item.applied = item.type === "percent" ? (Number(event.target.value) || 0) / 100 : Number(event.target.value) || 0; persist(); render(); } const mapSheet = event.target.dataset.mapSheet; if (mapSheet && state.pendingImport) { const sheets = state.pendingImport.analysis.priceSheets; state.pendingImport.analysis.priceSheets = event.target.checked ? [...new Set([...sheets, mapSheet])] : sheets.filter((name) => name !== mapSheet); } }

async function handleFile(file) { if (!file) return; state.importError = ""; state.pendingImport = null; state.importStage = 1; render(); try { state.pendingImport = await importWorkbookFile(file); state.importStage = 1; showToast(`${file.name} analysed locally; mapping review required`); } catch (error) { state.importStage = 0; state.importError = error.message; render(); showToast(`Import failed: ${error.message}`); } }
async function commitImport() { if (!state.pendingImport?.validation.canImport) return; const database = state.pendingImport.database; await saveDatabase(database); state.databases = [...state.databases.filter((entry) => entry.id !== database.id), database]; refreshRecords(); state.mode = "production"; state.lastImport = `${database.name} · ${database.recordsCount} rows · ${database.revision}`; state.importStage = 5; persist(); render(); }
function safeExcel(value) { if (typeof value !== "string") return value; return /^[=+\-@]/.test(value) ? `'${value}` : value; }
function safeRows(rows) { return rows.map((row) => row.map(safeExcel)); }
function downloadWorkbook() {
  const { rows, direct, indirect, total } = totals();
  if (!rows.length) return showToast("Add at least one source line before exporting.");
  const xlsx = globalThis.XLSX;
  if (!xlsx?.utils?.book_new) return showToast("The local XLSX writer is unavailable.");
  const sourceRows = rows.map((row, index) => [index + 1, row.record.database, row.record.revision, row.record.workbook, row.record.sheet, row.record.row, row.record.cell, row.record.reference, row.record.databaseId || "", row.record.sourceProject, row.record.country, row.record.year, row.record.currency, row.record.quality, row.record.qualityReason]);
  const breakdownRows = rows.flatMap((row, index) => row.calc.amounts.map((component) => [index + 1, row.record.description, component.name, component.componentType, component.rawValue, component.included ? "Yes" : "No", component.amount, component.calculationBase, component.note || ""]));
  const alternatives = currentResults().filter((result) => !rows.some((row) => row.record.id === result.record.id)).map((result) => [result.record.description, result.matchClass, result.score, result.differences?.join("; ") || "", result.record.sheet, result.record.cell, result.record.reference]);
  const sheets = {
    "01_Estimate_Summary": [["Asset Valuation Automation"], ["Project", state.project.name], ["Project number", state.project.number], ["Target country", state.project.country], ["Target cost year", state.project.targetYear], ["Currency", state.project.currency], ["Direct equipment total", direct], ["Indirect costs", indirect], ["Estimate total", total], ["Data mode", state.mode], ["Exported", new Date().toISOString()]],
    "02_Equipment_Estimate": [["Item", "Equipment type", "Description", "Specification", "Quantity", "Source basis", "Source currency", "Source year", "Target year", "Escalation factor", "Location factor", "Adjusted unit cost", "Line total", "Match class"], ...rows.map((row, index) => [index + 1, row.record.attributes?.equipmentType, row.record.description, Object.entries(row.record.attributes || {}).map(([key, value]) => `${key}: ${value}`).join("; "), row.calc.quantity, row.calc.historicalBasis, row.record.currency, row.record.year, row.settings.targetYear, row.calc.escalation.factor, row.calc.locationFactor, row.calc.targetUnitCost, row.calc.total, row.matchClass || "Selected source"])],
    "03_Cost_Breakdown": [["Item", "Description", "Component", "Type", "Raw value", "Included", "Applied amount", "Calculation base", "Source note"], ...breakdownRows],
    "04_Inflation_Escalation": [["Item", "Source year", "Target year", "Method", "Factor", "Basis", "Index/provider"], ...rows.map((row, index) => [index + 1, row.record.year, row.settings.targetYear, row.settings.method, row.calc.escalation.factor, row.calc.escalation.basis, row.calc.escalation.index?.provider || "Not used"])],
    "05_Country_Adjustments": [["Item", "Source country", "Target country", "Approved recommendation", "Applied factor", "Status", "Rationale"], ...rows.map((row, index) => [index + 1, row.record.country, state.project.country, "Unavailable", row.calc.locationFactor, "Unadjusted — review required", LOCATION_FACTOR_POLICY.rationale])],
    "06_Source_Register": [["Item", "Database", "Revision", "Workbook", "Worksheet", "Row", "Cell", "Reference", "Workbook SHA-256", "Source project", "Country", "Year", "Currency", "Quality", "Quality rationale"], ...sourceRows],
    "07_Assumptions": [["Assumption / override", "Applied value", "Basis", "Status"], ["Location factor", "Unavailable", LOCATION_FACTOR_POLICY.rationale, "Review required"], ...state.indirectCosts.map((item) => [item.name, item.enabled ? item.applied : "Disabled", item.basis, item.enabled ? "Applied by user" : "Not applied"])],
    "08_Alternative_Matches": [["Description", "Match class", "Score", "Differences", "Worksheet", "Cell", "Reference"], ...alternatives],
    "09_Basis_of_Estimate": [["Field", "Value"], ["Methodology", "Selected components → escalation → location factor → quantity"], ["Source status", state.mode === "demo" ? DEMO_DATA_NOTICE : `${state.records.length} committed imported records`], ["Calculation engine", "Fixed-point decimal, internal 6 places; display/export rounding at boundary"], ["Limitations", "Existing asset valuation remains under FAR method validation; country factor is unadjusted without approved source."], ["Export date", dateLabel()], ["Professional review", "Required before commercial use"]],
  };
  const workbook = xlsx.utils.book_new();
  for (const [name, values] of Object.entries(sheets)) { const sheet = xlsx.utils.aoa_to_sheet(safeRows(values)); sheet["!freeze"] = { xSplit: 0, ySplit: 1 }; xlsx.utils.book_append_sheet(workbook, sheet, name); }
  const output = xlsx.write(workbook, { bookType: "xlsx", type: "array", compression: true });
  const url = URL.createObjectURL(new Blob([output], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }));
  const link = document.createElement("a"); link.href = url; link.download = `${state.project.number || "asset-valuation"}_estimate.xlsx`; document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 5000); showToast("Traceability XLSX workbook downloaded");
}

document.addEventListener("click", async (event) => {
  const target = event.target.closest("[data-action]"); if (!target) return;
  const action = target.dataset.action;
  if (action === "navigate") { state.page = target.dataset.page; state.modal = null; render(); }
  else if (action === "choose-file") document.querySelector("#file-input")?.click();
  else if (action === "open-builder") openBuilder(target.dataset.id, target.dataset.matchClass || "Exact source match");
  else if (action === "view-source") { state.modal = { type: "source", id: target.dataset.id }; render(); }
  else if (action === "close-modal" && (!event.target.closest("[data-modal-content]") || event.target.closest(".modal-close"))) { state.modal = null; render(); }
  else if (action === "add-estimate") addEstimate();
  else if (action === "remove-item") { state.items = state.items.filter((item) => item.id !== target.dataset.item); persist(); render(); showToast("Estimate line removed"); }
  else if (action === "clear-filters") { state.filters = { query: "", equipmentType: "All equipment", voltage: "Any voltage", rating: "Any rating", manufacturer: "Any manufacturer", country: "Any country" }; render(); }
  else if (action === "apply-search") { const input = document.querySelector('input[data-field="search-query"]'); if (input) state.filters.query = input.value; render(); }
  else if (action === "export") downloadWorkbook();
  else if (action === "new-revision") { const snapshot = makeSnapshot(state.project, currentItemRows().map((item) => ({ ...item, total: item.calc.total })), state.indirectCosts); state.revisions.push(snapshot); persist(); showToast(`Revision ${state.revisions.length - 1} snapshot created`); }
  else if (action === "enable-demo") { state.mode = "demo"; state.page = "search"; state.filters.query = "Power Transformer"; persist(); render(); }
  else if (action === "production-mode") { state.mode = "production"; state.page = "databases"; persist(); render(); }
  else if (action === "toggle-db") { const database = state.databases.find((entry) => entry.id === target.dataset.id); if (database) { database.enabled = database.enabled === false; await saveDatabase(database); refreshRecords(); persist(); render(); } }
  else if (action === "import-next") { if (state.importStage === 2 && state.pendingImport) { const analysis = state.pendingImport.analysis; const allowed = new Set(analysis.priceSheets); analysis.records = analysis.records.filter((record) => allowed.has(record.sheet)); analysis.recordCount = analysis.records.length; analysis.sourceCount = new Set(analysis.records.map((record) => `${record.sheet}:${record.row}:${record.cell}`)).size; state.pendingImport.validation = validateImport(analysis); state.pendingImport.database.records = analysis.records; state.pendingImport.database.recordsCount = analysis.recordCount; state.pendingImport.database.sources = analysis.sourceCount; } state.importStage = Math.min(4, state.importStage + 1); render(); }
  else if (action === "back-import") { state.importStage = Math.max(1, state.importStage - 1); render(); }
  else if (action === "cancel-import") { state.pendingImport = null; state.importStage = 0; state.importError = ""; render(); }
  else if (action === "commit-import") { target.disabled = true; await commitImport(); }
  else if (action === "finish-import") { state.pendingImport = null; state.importStage = 0; state.page = "search"; state.filters.query = ""; render(); }
});
document.addEventListener("input", handleInput);
document.addEventListener("change", handleChange);
document.addEventListener("keydown", (event) => { if (event.key === "Escape" && state.modal) { state.modal = null; render(); } if (event.key === "Enter" && event.target.matches('input[data-field="search-query"]')) { state.filters.query = event.target.value; render(); } });
document.querySelector("#file-input").addEventListener("change", async (event) => { await handleFile(event.target.files[0]); event.target.value = ""; });

async function init() { try { const [databases, workspace] = await Promise.all([listDatabases(), loadWorkspace()]); state.databases = databases || []; if (workspace) { state.mode = workspace.mode === "demo" ? "demo" : "production"; state.project = { ...state.project, ...(workspace.project || {}) }; state.items = workspace.items || []; state.revisions = workspace.revisions || []; state.indirectCosts = workspace.indirectCosts || state.indirectCosts; } refreshRecords(); state.ready = true; render(); } catch (error) { state.ready = true; state.importError = `Local storage unavailable: ${error.message}`; render(); } }
init();
